  src: url("./media/boxicons.eot");
  src:
    url("./media/boxicons.eot") format("embedded-opentype"),
    url("./media/boxicons.woff2") format("woff2"),
    url("./media/boxicons.woff") format("woff"),
    url("./media/boxicons.ttf") format("truetype"),
    url("./media/boxicons.svg?#boxicons") format("svg");
}
.bx {
  font-family: boxicons !important;
  font-weight: 400;
  font-style: normal;
  font-variant: normal;
  line-height: 1;
  text-rendering: auto;
  display: inline-block;
  text-transform: none;
  speak: none;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}
.bx-ul {
  margin-left: 2em;
  padding-left: 0;
  list-style: none;
}
.bx-ul > li {
  position: relative;
}
.bx-ul .bx {
  font-size: inherit;
  line-height: inherit;
  position: absolute;
  left: -2em;
  width: 2em;
  text-align: center;
}
@-webkit-keyframes spin {
  0% {
    -webkit-transform: rotate(0);
